package words

import (
	"strings"
	"unicode"
)

func WordFrequency(s string) map[string]int {
	freq := make(map[string]int)
	var current strings.Builder
	inWord := false

	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			current.WriteRune(r)
			inWord = true
		} else {
			if inWord {
				word := strings.ToLower(current.String())
				freq[word]++
				current.Reset()
				inWord = false
			}
		}
	}
	if inWord {
		word := strings.ToLower(current.String())
		freq[word]++
	}

	return freq
}

