package words

import (
	"strings"
	"unicode"
)

func WordFrequency(s string) map[string]int {
	freq := make(map[string]int)
	var current []rune

	flush := func() {
		if len(current) > 0 {
			word := strings.ToLower(string(current))
			freq[word]++
			current = current[:0]
		}
	}

	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			current = append(current, r)
		} else {
			flush()
		}
	}
	flush()

	return freq
}

