package ledger

import (
	"fmt"
)

type ledger struct {
	balances map[string]int64
	history  map[string][]Entry
}

func NewLedger(starting map[string]int64) Ledger {
	l := &ledger{
		balances: make(map[string]int64),
		history:  make(map[string][]Entry),
	}
	for account, bal := range starting {
		l.balances[account] = bal
	}
	return l
}

func (l *ledger) Record(e Entry) error {
	if e.Amount == 0 {
		return ErrZeroAmount
	}

	current, exists := l.balances[e.Account]
	if !exists {
		current = 0
	}

	newBalance := current + e.Amount
	if newBalance < 0 {
		return fmt.Errorf("ledger: insufficient funds for account %q: %w", e.Account, ErrInsufficient)
	}

	l.balances[e.Account] = newBalance
	l.history[e.Account] = append(l.history[e.Account], e)
	return nil
}

func (l *ledger) Balance(account string) (int64, error) {
	bal, exists := l.balances[account]
	if !exists {
		return 0, ErrUnknownAccount
	}
	return bal, nil
}

func (l *ledger) History(account string) ([]Entry, error) {
	if _, exists := l.balances[account]; !exists {
		return nil, ErrUnknownAccount
	}
	entries := l.history[account]
	out := make([]Entry, len(entries))
	copy(out, entries)
	return out, nil
}

