function parseDuration(s: string): number {
  // Bare number means seconds
  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  // Full pattern: one or more components (digits + unit letter),
  // separated by nothing, whitespace, or comma+whitespace
  const pattern = /^(\d+[hms])(?:(?:\s+|,\s+)?\d+[hms])*$/;

  if (!pattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  const components = s.match(/\d+[hms]/g)!;

  let total = 0;
  for (const comp of components) {
    const num = parseInt(comp.slice(0, -1), 10);
    const unit = comp.slice(-1);
    switch (unit) {
      case 'h':
        total += num * 3600;
        break;
      case 'm':
        total += num * 60;
        break;
      case 's':
        total += num;
        break;
    }
  }

  return total;
}

