import { ConfigSchema, type Config } from "./schema";

export type ParseResult =
  | { ok: true; value: Config }
  | { ok: false; issues: { path: string; code: string }[] };

export function loadConfig(raw: unknown): ParseResult {
  const result = ConfigSchema.safeParse(raw);

  if (result.success) {
    return { ok: true, value: result.data };
  }

  const issues = result.error.issues
    .map((issue) => ({
      path: issue.path.join("."),
      code: issue.code,
    }))
    .sort((a, b) => {
      if (a.path !== b.path) return a.path < b.path ? -1 : 1;
      if (a.code !== b.code) return a.code < b.code ? -1 : 1;
      return 0;
    });

  return { ok: false, issues };
}

import { ConfigSchema, type Config } from "./schema";

export type ParseResult =
  | { ok: true; value: Config }
  | { ok: false; issues: { path: string; code: string }[] };

export function loadConfig(raw: unknown): ParseResult {
  const result = ConfigSchema.safeParse(raw);

  if (result.success) {
    return { ok: true, value: result.data };
  }

  const issues = result.error.issues.map((issue) => ({
    path: issue.path.join("."),
    code: issue.code,
  }));

  issues.sort((a, b) => {
    if (a.path < b.path) return -1;
    if (a.path > b.path) return 1;
    if (a.code < b.code) return -1;
    if (a.code > b.code) return 1;
    return 0;
  });

  return { ok: false, issues };
}

export interface EvictionStats {
  hits: number;
  misses: number;
  evictions: number;
  expirations: number;
}

interface Entry<V> {
  value: V;
  expiresAt: number;
}

export class ExpiringLRU<K, V> {
  private map: Map<K, Entry<V>>;
  private capacity: number;
  private defaultTtlMs: number;
  private now: () => number;
  private _hits = 0;
  private _misses = 0;
  private _evictions = 0;
  private _expirations = 0;

  constructor(capacity: number, defaultTtlMs: number, now?: () => number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.defaultTtlMs = defaultTtlMs;
    this.now = now ?? Date.now;
    this.map = new Map();
  }

  private isExpired(entry: Entry<V>): boolean {
    return this.now() >= entry.expiresAt;
  }

  get size(): number {
    for (const [key, entry] of this.map) {
      if (this.isExpired(entry)) {
        this.map.delete(key);
        this._expirations++;
      }
    }
    return this.map.size;
  }

  get stats(): EvictionStats {
    return {
      hits: this._hits,
      misses: this._misses,
      evictions: this._evictions,
      expirations: this._expirations,
    };
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this._misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      this._misses++;
      return undefined;
    }
    // Live: refresh recency by re-inserting at end
    this.map.delete(key);
    this.map.set(key, entry);
    this._hits++;
    return entry.value;
  }

  peek(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this._misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      this._misses++;
      return undefined;
    }
    // Live: do NOT refresh recency
    this._hits++;
    return entry.value;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const existing = this.map.get(key);
    const ttl = ttlMs ?? this.defaultTtlMs;
    const expiresAt = this.now() + ttl;

    if (existing !== undefined) {
      if (this.isExpired(existing)) {
        this._expirations++;
      }
      // Replace in place and mark most recently used
      this.map.delete(key);
      this.map.set(key, { value, expiresAt });
    } else {
      // New key: check if we need to make room
      if (this.map.size >= this.capacity) {
        let madeRoom = false;
        // First, try to free a slot by removing expired entries from LRU end
        for (const [k, e] of this.map) {
          if (this.isExpired(e)) {
            this.map.delete(k);
            this._expirations++;
            if (this.map.size < this.capacity) {
              madeRoom = true;
              break;
            }
          }
        }
        if (!madeRoom) {
          // Evict the least recently used live entry
          const lruKey = this.map.keys().next().value;
          this.map.delete(lruKey);
          this._evictions++;
        }
      }
      this.map.set(key, { value, expiresAt });
    }
  }

  delete(key: K): boolean {
    const entry = this.map.get(key);
    if (entry === undefined) {
      return false;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      return false;
    }
    this.map.delete(key);
    return true;
  }
}

export interface EvictionStats {
  hits: number;
  misses: number;
  evictions: number;
  expirations: number;
}

interface Entry<V> {
  value: V;
  expiresAt: number;
}

export class ExpiringLRU<K, V> {
  private map: Map<K, Entry<V>>;
  private capacity: number;
  private defaultTtlMs: number;
  private now: () => number;
  private hits: number;
  private misses: number;
  private evictions: number;
  private expirations: number;

  constructor(capacity: number, defaultTtlMs: number, now?: () => number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.defaultTtlMs = defaultTtlMs;
    this.now = now ?? Date.now;
    this.map = new Map();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
    this.expirations = 0;
  }

  private isExpired(entry: Entry<V>): boolean {
    return this.now() >= entry.expiresAt;
  }

  private refreshRecency(key: K): void {
    const entry = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, entry);
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this.misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this.expirations++;
      this.misses++;
      return undefined;
    }
    this.hits++;
    this.refreshRecency(key);
    return entry.value;
  }

  peek(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this.misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this.expirations++;
      this.misses++;
      return undefined;
    }
    this.hits++;
    return entry.value;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const ttl = ttlMs ?? this.defaultTtlMs;
    const expiresAt = this.now() + ttl;
    const existing = this.map.get(key);

    if (existing !== undefined) {
      if (this.isExpired(existing)) {
        this.expirations++;
      }
      this.map.delete(key);
      this.map.set(key, { value, expiresAt });
    } else {
      while (this.map.size >= this.capacity) {
        const [k, e] = this.map.entries().next().value!;
        this.map.delete(k);
        if (this.isExpired(e)) {
          this.expirations++;
        } else {
          this.evictions++;
        }
      }
      this.map.set(key, { value, expiresAt });
    }
  }

  delete(key: K): boolean {
    const entry = this.map.get(key);
    if (entry === undefined) {
      return false;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this.expirations++;
      return false;
    }
    this.map.delete(key);
    return true;
  }

  get size(): number {
    for (const [k, e] of this.map) {
      if (this.isExpired(e)) {
        this.map.delete(k);
        this.expirations++;
      }
    }
    return this.map.size;
  }

  get stats(): EvictionStats {
    return {
      hits: this.hits,
      misses: this.misses,
      evictions: this.evictions,
      expirations: this.expirations,
    };
  }
}

package words

import (
	"strings"
	"unicode"
)

// WordFrequency counts how many times each word appears in s.
// A word is a maximal run of Unicode letters or digits. Counting is
// case-insensitive.
func WordFrequency(s string) map[string]int {
	freq := make(map[string]int)

	var sb strings.Builder
	flush := func() {
		if sb.Len() > 0 {
			word := strings.ToLower(sb.String())
			freq[word]++
			sb.Reset()
		}
	}

	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			sb.WriteRune(r)
		} else {
			flush()
		}
	}
	flush()

	return freq
}

