package ledger

type accountData struct {
	balance int64
	history []Entry
}

type ledger struct {
	accounts map[string]*accountData
}

// NewLedger creates a new Ledger with the given starting balances.
func NewLedger(starting map[string]int64) Ledger {
	l := &ledger{
		accounts: make(map[string]*accountData),
	}
	for acct, bal := range starting {
		l.accounts[acct] = &accountData{
			balance: bal,
			history: nil,
		}
	}
	return l
}

func (l *ledger) Record(e Entry) error {
	if e.Amount == 0 {
		return ErrZeroAmount
	}

	acct, ok := l.accounts[e.Account]
	if !ok {
		acct = &accountData{balance: 0, history: nil}
	}

	newBalance := acct.balance + e.Amount
	if newBalance < 0 {
		return ErrInsufficient
	}

	acct.balance = newBalance
	acct.history = append(acct.history, e)
	l.accounts[e.Account] = acct

	return nil
}

func (l *ledger) Balance(account string) (int64, error) {
	acct, ok := l.accounts[account]
	if !ok {
		return 0, ErrUnknownAccount
	}
	return acct.balance, nil
}

func (l *ledger) History(account string) ([]Entry, error) {
	acct, ok := l.accounts[account]
	if !ok {
		return nil, ErrUnknownAccount
	}
	result := make([]Entry, len(acct.history))
	copy(result, acct.history)
	return result, nil
}

