export function parseDuration(s: string): number {
  const original = s;

  const invalid = () => {
    throw new Error(`invalid duration: ${original}`);
  };

  if (typeof s !== "string") {
    invalid();
  }

  const trimmed = s.trim();

  if (trimmed.length === 0) {
    invalid();
  }

  // Bare number (no units at all) means seconds, but only if the whole
  // trimmed string is just digits.
  if (/^\d+$/.test(trimmed)) {
    return parseInt(trimmed, 10);
  }

  let i = 0;
  let total = 0;
  let first = true;

  while (i < trimmed.length) {
    if (!first) {
      const sepMatch = /^(,\s+|\s+)/.exec(trimmed.slice(i));
      if (sepMatch) {
        i += sepMatch[0].length;
      }
      // If no separator matched, we allow immediate concatenation
      // (e.g. "1h30m") and just try to parse the next component directly.
    }

    const numMatch = /^\d+/.exec(trimmed.slice(i));
    if (!numMatch) {
      invalid();
    }

    const numStr = numMatch![0];
    i += numStr.length;

    const unitChar = trimmed[i];

    if (unitChar === "h" || unitChar === "m" || unitChar === "s") {
      i += 1;
      const value = parseInt(numStr, 10);
      if (unitChar === "h") {
        total += value * 3600;
      } else if (unitChar === "m") {
        total += value * 60;
      } else {
        total += value;
      }
    } else {
      // A bare number without a unit is only valid if it's the entire
      // string (handled above). Any other bare number here is invalid.
      invalid();
    }

    first = false;
  }

  return total;
}

export function parseDuration(s: string): number {
  const invalid = () => new Error(`invalid duration: ${s}`);

  if (typeof s !== 'string' || s.length === 0) {
    throw invalid();
  }

  // Split on comma+whitespace or plain whitespace separators.
  const tokens = s.split(/,\s+|\s+/);

  let total = 0;

  for (const token of tokens) {
    if (token.length === 0) {
      throw invalid();
    }

    // Extract subcomponents: one or more digits followed by an optional unit.
    const matches = token.match(/\d+[hms]?/g);
    const joined = matches ? matches.join('') : '';

    // If the concatenation of matched subcomponents doesn't reconstruct
    // the original token exactly, the token contains invalid characters,
    // an unknown unit, a zero-length component, a negative sign, etc.
    if (!matches || joined !== token) {
      throw invalid();
    }

    for (const m of matches) {
      const unitMatch = m.match(/[hms]$/);
      const unit = unitMatch ? unitMatch[0] : '';
      const numPart = unit ? m.slice(0, -1) : m;

      if (numPart.length === 0) {
        throw invalid();
      }

      const num = parseInt(numPart, 10);

      if (Number.isNaN(num)) {
        throw invalid();
      }

      switch (unit) {
        case 'h':
          total += num * 3600;
          break;
        case 'm':
          total += num * 60;
          break;
        case 's':
        case '':
          total += num;
          break;
        default:
          throw invalid();
      }
    }
  }

  return total;
}

import { ConfigSchema, type Config } from "./schema";

export type ParseResult =
  | { ok: true; value: Config }
  | { ok: false; issues: { path: string; code: string }[] };

export function loadConfig(raw: unknown): ParseResult {
  const result = ConfigSchema.safeParse(raw);

  if (result.success) {
    return { ok: true, value: result.data };
  }

  const issues = result.error.issues.map((issue) => ({
    path: issue.path.join("."),
    code: issue.code,
  }));

  issues.sort((a, b) => {
    if (a.path < b.path) return -1;
    if (a.path > b.path) return 1;
    if (a.code < b.code) return -1;
    if (a.code > b.code) return 1;
    return 0;
  });

  return { ok: false, issues };
}

