export interface EvictionStats {
  hits: number;
  misses: number;
  evictions: number;
  expirations: number;
}

interface Entry<V> {
  value: V;
  expiry: number;
}

export class ExpiringLRU<K, V> {
  private capacity: number;
  private defaultTtlMs: number;
  private now: () => number;
  private map: Map<K, Entry<V>>;
  private statsInternal: EvictionStats;

  constructor(capacity: number, defaultTtlMs: number, now: () => number = Date.now) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.defaultTtlMs = defaultTtlMs;
    this.now = now;
    this.map = new Map<K, Entry<V>>();
    this.statsInternal = {
      hits: 0,
      misses: 0,
      evictions: 0,
      expirations: 0,
    };
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      this.statsInternal.misses++;
      return undefined;
    }
    const entry = this.map.get(key)!;
    const t = this.now();
    if (t >= entry.expiry) {
      this.map.delete(key);
      this.statsInternal.expirations++;
      this.statsInternal.misses++;
      return undefined;
    }
    // live hit: refresh recency
    this.map.delete(key);
    this.map.set(key, entry);
    this.statsInternal.hits++;
    return entry.value;
  }

  peek(key: K): V | undefined {
    if (!this.map.has(key)) {
      this.statsInternal.misses++;
      return undefined;
    }
    const entry = this.map.get(key)!;
    const t = this.now();
    if (t >= entry.expiry) {
      this.map.delete(key);
      this.statsInternal.expirations++;
      this.statsInternal.misses++;
      return undefined;
    }
    this.statsInternal.hits++;
    return entry.value;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const t = this.now();
    const effectiveTtl = ttlMs ?? this.defaultTtlMs;

    if (this.map.has(key)) {
      const entry = this.map.get(key)!;
      if (t >= entry.expiry) {
        this.statsInternal.expirations++;
      }
      this.map.delete(key);
      this.map.set(key, { value, expiry: t + effectiveTtl });
      return;
    }

    // new key: ensure capacity
    while (this.map.size >= this.capacity) {
      const firstKeyResult = this.map.keys().next();
      if (firstKeyResult.done) {
        break;
      }
      const firstKey = firstKeyResult.value;
      const firstEntry = this.map.get(firstKey)!;
      if (t >= firstEntry.expiry) {
        this.map.delete(firstKey);
        this.statsInternal.expirations++;
        // continue loop to re-check capacity condition
      } else {
        this.map.delete(firstKey);
        this.statsInternal.evictions++;
        break;
      }
    }

    this.map.set(key, { value, expiry: t + effectiveTtl });
  }

  delete(key: K): boolean {
    if (!this.map.has(key)) {
      return false;
    }
    const entry = this.map.get(key)!;
    const t = this.now();
    if (t >= entry.expiry) {
      this.map.delete(key);
      this.statsInternal.expirations++;
      return false;
    }
    this.map.delete(key);
    return true;
  }

  get size(): number {
    const t = this.now();
    const expiredKeys: K[] = [];
    for (const [k, entry] of this.map) {
      if (t >= entry.expiry) {
        expiredKeys.push(k);
      }
    }
    for (const k of expiredKeys) {
      this.map.delete(k);
      this.statsInternal.expirations++;
    }
    return this.map.size;
  }

  get stats(): EvictionStats {
    return {
      hits: this.statsInternal.hits,
      misses: this.statsInternal.misses,
      evictions: this.statsInternal.evictions,
      expirations: this.statsInternal.expirations,
    };
  }
}

export interface EvictionStats {
  hits: number;
  misses: number;
  evictions: number;
  expirations: number;
}

interface Entry<V> {
  value: V;
  expiryAt: number;
}

export class ExpiringLRU<K, V> {
  private capacity: number;
  private defaultTtlMs: number;
  private now: () => number;
  private map: Map<K, Entry<V>>;
  private _hits = 0;
  private _misses = 0;
  private _evictions = 0;
  private _expirations = 0;

  constructor(capacity: number, defaultTtlMs: number, now: () => number = Date.now) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.defaultTtlMs = defaultTtlMs;
    this.now = now;
    this.map = new Map();
  }

  private isExpired(entry: Entry<V>): boolean {
    return this.now() >= entry.expiryAt;
  }

  get(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this._misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      this._misses++;
      return undefined;
    }
    this._hits++;
    // refresh recency: move to end
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }

  peek(key: K): V | undefined {
    const entry = this.map.get(key);
    if (entry === undefined) {
      this._misses++;
      return undefined;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      this._misses++;
      return undefined;
    }
    this._hits++;
    return entry.value;
  }

  set(key: K, value: V, ttlMs?: number): void {
    const ttl = ttlMs ?? this.defaultTtlMs;
    const existing = this.map.get(key);
    if (existing !== undefined) {
      if (this.isExpired(existing)) {
        this._expirations++;
      }
      this.map.delete(key);
      const newEntry: Entry<V> = { value, expiryAt: this.now() + ttl };
      this.map.set(key, newEntry);
      return;
    }

    // new key: enforce capacity before insertion
    while (this.map.size >= this.capacity) {
      const firstKeyResult = this.map.keys().next();
      if (firstKeyResult.done) {
        break;
      }
      const firstKey = firstKeyResult.value;
      const firstEntry = this.map.get(firstKey)!;
      this.map.delete(firstKey);
      if (this.isExpired(firstEntry)) {
        this._expirations++;
      } else {
        this._evictions++;
      }
    }

    const newEntry: Entry<V> = { value, expiryAt: this.now() + ttl };
    this.map.set(key, newEntry);
  }

  delete(key: K): boolean {
    const entry = this.map.get(key);
    if (entry === undefined) {
      return false;
    }
    if (this.isExpired(entry)) {
      this.map.delete(key);
      this._expirations++;
      return false;
    }
    this.map.delete(key);
    return true;
  }

  get size(): number {
    // eagerly prune expired entries
    const keysToCheck = Array.from(this.map.keys());
    for (const key of keysToCheck) {
      const entry = this.map.get(key);
      if (entry !== undefined && this.isExpired(entry)) {
        this.map.delete(key);
        this._expirations++;
      }
    }
    return this.map.size;
  }

  get stats(): EvictionStats {
    return {
      hits: this._hits,
      misses: this._misses,
      evictions: this._evictions,
      expirations: this._expirations,
    };
  }
}
